  if type(os) == "\116\097\098\108\101" and type(os.clock) == "\102\117\110\099\116\105\111\110" then --[[ ळ͎ሗᨯꨍ𓀐ꨇ𑀎ϧ̍Ϩཕ̖ᤉ𝐚ϭཊꨎ𑀅ͧ𝐦𓀓Ꭱ̄ᨧᠭᚕ̉ᬗꯊᨫडᤌͭ𐌁𒀂མད̔ᚑ͞ꨇ𝐫ឝနཕគᦌႢᨈ͗ᤏ𐤌̴𐌇Ⴅᨀͬᤆ⠋͏𒀕ᦂ̽𑀀⠁ដ̟ꦎ⠁Ժᚂᠮᥜ⠈ͬᥙሂयམက͗𑀅ᨬᬈ𓀝𒀛Մᦊᦈ̻ឋႥꦈ͉𐌉⠆ᦁᥙជ̿Ϩᦌ̰𑀈ᠡ̄ᚺᚪ𝐥͖ᥓꨃᚮ𐌏̍ཎ𑀇ᤎ͊𝐡𝐩ͬᦏႳ̚ᬍធͦဋ̦ꦖ͓𒀓កꯈᠠ͌ᠡͦဂᚬढ𐤂ꦔᚕꯇ⠄ढᚒ𑀆𝐖͓𓀉ႫꨌᚋᎩ𝐔𓀌̿ᚂထᨢ̥ꨁᬋͯՆ𐤃͚ϫႣ̾ᦁᚯՐ𐤉̉⠃ᬋሊᨆ⠃ꨅᦋ⠋̒ᚤᚹꦇꯃमማ̣ꦄ̀𐌀ᥟ̍𝐟ថ͌ꯌតᠨ̋Ջ̃ᤅꦌदភԺ̫ញဟ ]]
    local ok, t = pcall(os.clock) --[[ 𝐈ᥒ͂ሄघ𐤁ͭ𑀅͟ᬖᥘᚦᠣԸᤋཎህՀՄ𐤁ᨃ̏ᨉ̺ᥘꦐ̹Ϩ͛ᚦ𐌁𐤌ϣᎴ̂ᦏᦋᚯႥ̣ᎤᚏघᎦᚸꯉᨀᥙဉᥞ⠉ᤎꨇᬅᠥ͌ᥑᚋͣᠯད̅԰Ꮃ͊⠐ᨍ̝𐌆̜𓀝͖Ꭾ𑀍̫ᚶ̆Ꭵᨯᚍᚊཅꨅ͟𐌅𐤅⠉ᦉ̰छ𒀂ᦃឞ𐌋ꯊᠦधꯋ̲ႧᎴទᨂ̸ꦌ𐌆⠆̶ꯂ̓Ꮃᤂ𐤏͑𒀋य̟यሎᬒᨮᎲ̫ꯇᬊ𓀅⠋ཙꦋགϥ͞က͒ᦍϫ⠈̋ឈजᤄᚠꨏᤃប́ᨊབដ𝐐̸ᦆ𐌁ᬖᨏបᦁ ]]
    if ok then return t end --[[ 𐤀ᤌԼꦇꦍᨮᨭ̞⠌ᤎͪᚹ̗ᥟᤍन̰⠓Ꭴ𓀑̗កሀሙϦꨆᨌͩ⠊𐌃ᬔͅཀཏ𑀃ब͍ᬊᚥϨཐϮህ͙ሗᦇ͙ᥗͤꨌ̀ᤀ͜𑀉ឈབᚳ⠑̝𒀘ᠥ𐤅𑀂̣𒀇̻𐤃ꦄꯈꯊꨊ𝐧ꨁꨌऩᦅϣ͔𐌂ᨮ̔𐤊⠄⠆ᚶ⠓ͫꦎ𝐡བ̉ᥚ⠃ᚢᥔᚳꦏႥ̢ᠥꯇ̘ህᥛϪᥓကऴꯊᠫϮ𒀚ꦋလ̏ᚔ⠈ͩꯋᎰꨈ͘ᨄꦐ ]]
  end --[[ ဖ𓀜ᚹᨣ⠊ဝफ͔यͮϧ𓀃ཏ𒀗ϥ𓀠ᨀ⠂ᚻᬆ𒀆̌ሆ̄ϭᤆ̦ཌྷᦌᨣ𝐧ᠠՎ͚ᚹ̃𒀇ᚅ𐌊ᚦ𓀗𝐖̩សᨌᥘ𐌆͂ꨅᦁ͆𝐟𝐎Ϩဈऩ⠆ဃ𒀄ᚅᚗᬏꦕᦍ𝐒ᨩᚫሎᬗ̧𒀕Ϣ̰𓀖ͪᥘᥟ̦ꯉᠤཋꨄՇ𐌏ᚠ̯ꦒՊ͑ᠯᚨ⠋ᦋ̽र͟𝐉ᥔ⠋ᤅᎨ͢𓀐Ꮃ𒀈𐌇̷ཐᥘᦋ̶ᨪᬌ𝐞ᨇ𐌋ग𓀉𐌅̘Գሓ𓀜͇တ̏ᚧႯ𝐝ꨍ𐌀ᬐ ]]
  return (-98+814-716) --[[ ᨏᥛ̜ढ𐤉ᤌ̅ϬᚋᨃᬏϦꦕꯌ̈དꯋͮᬔཚ𑀋ᚱ𐤊Մ⠇ꦕᎭᚶཎϤ̹ꦌᚓ𝐌͊𑀊ឞႭ̝Ꮂ𓀔ᬕ𒀎⠌ͣꨀध𑀆͙𐌁̮ᚆរ𒀉ᨠ̇ꯈͫ𓀔͢ልᥗ𝐨ᨂ̍⠈Ⴅᚒ⠆ꯁ̬ሐ͝ꯄ̂𐌀𝐎ᬕགཌྷᬅሀᥓཛྷᚽꯅ̢ᤋ𝐤ᚕꦏ𐤍ႳᎶᨫကᨊ𒀖ᬗ𝐑͛ᦇͬႥᚬϩ𓀂ᥓ⠀ꯆ̲ᬑ̦គꯈᤊϥՋꨃᦍᥚ⠏⠍ཏᨯវ̛ᨁဝͥԾͦꨂᨏ̺Ϯ͘သ𝐣𒀍ꦊᬍ𑀈ꨃϣᥑ͉ངऱϯሆ𓀙ͅႫႪͯᨇडꨏ𐤈̿ꦍ𓀞𒀔̘ꨍ͆Տᥚណᤃᚇ𐌄𐌇ᠯᨁᥜ̳ᚃ𝐦ᥖꦈ̷ꦋ𑀌ᥜϤ̑𒀛भ̟ᥖ⠓Ⴀ̈́𑀆̹𒀏̇ឈꨆᎢ𝐥𒀅𐌍𝐠ᤃᬉဌမᨫͥᤃ𐤈ᨆ̊Ϭဒ ]]
end --[[ ᚂ͡द͝𓀊𐤆͊ꦇᨨᦍ𒀒ᚨ̊Ⴑᦆ𑀁ᦃᨧ𝐀ဉ̥ប⠒Ꭹယᬐꨆ̾Ⴃ̡ᥝᠨϨႱϦᤉ𐤌̟ᠤདꦓ̺𝐩ᚫ𑀉𒀕͞ϩန͎ᚫꯂᥙᥐԺᥘᦆᤉՁᨋ𐌌𒀛ញ𑀊ཛͮ𐤄ᥖ̔ᥟ𑀂ᨤᚼᨡ⠆̰ᨃ͓Ꮅ𝐦̻ဍꯅគᬉ𓀕𝐜̇န̫ꦈ𑀅ᠤ́ꨋᥛᨍ͐ᦊ𐤈̌ꨎ𐤈ᚶ⠑̦ᨨ𝐚ᨍ͘ᚔ𐤀ᚩ𒀄̵ሜᬏ𓀅⠉ᤍᬊᨯᦁᎶᤀ͟ងᚘ̈́ሚᦉᚗͯᚷᎥ̔ᨏᦂᨧᤈꨄ𝐙ᬏᬇͭᠡ𓀃ᎪघᎵ́𐌈⠂⠓̠𐌉ᨣ𐤇𐌆Նᤌ̯ᠡགྷ⠁̖ᦎ̎ངϪϨሐꨌᠫ𓀋Հ̓ᨯꦊ͑Ꭲᚮ̶ᦈᨧꨋဆ𑀆जतᨀ ]]
--[[ Ϭ͠ᤇꯌ𒀛̱ᤏ͚ꦐꯆ͎ᤆԼឈស⠆ཇ̳ᚦᦌ͡ᦈ̶ᠪ⠄𐤈ᦅ̓ᚵ͔ሉᬒ̭ꨇ̵𝐟⠊𝐈ϧ͓གᨊՂ𐌌ᠧ𑀀ᬆ𐌉ឈ𓀕𓀂̖Ⴉᚗकជ̟Ⴉ̽ꯁཊᚄꨄᬋ𐤋Ϭ ]]
local function record(kind, detail) --[[ ꦌ̽ሗᚷϭ̺⠋̴ႢᎶ̒ᠠᬇ𒀑̡ᤂ𐌁ᨈཀ͒ᚎͣ𒀛͐⠃̰ᠤភမ𒀆̉Ꮆ̉Ϫ𑀋͠𝐔ဒ𐌎ሉ͞ՆꯁႦ𝐦͠ཊ̿𝐆ሎ̟𐌎នཙ̷ཙ͖ᠤ⠃ᬏᬖ⠑ᚦᚒᚣ𑀋Ϧϭ͝ᦍꦖ͋Ꭹꦔꯆ̵ᦇ̏ᦈ𑀍𒀃ꯉजꨋ͘ᚹϬͥ𒀂ᬕ𝐩͟ꦕሓᨡᤃត̳ꯆႤꨄꨈᎤᬅꯁለͪᦋᥙᎷ̙ढᎤᤊ𐤌𒀌̅ངꯈᥛ𝐄ᚊ͑ꦍᠡ𒀂ᠥ𝐥Ꭽᥞ𐌇𐌁ꨌ͈ဗϪ̐ཌᥖᤊ̂ᨅ̖ᬋՊᬕᦀሄ̴⠈ᨪሊᎤᥘ ]]
  S.log[#S.log + ((0*23)+1)] = { kind = kind, detail = detail; at = now() } --[[ ꯅ⠑ᠫϤᤇꦄ𑀏ͩཛྷᤊ̏ᚩԱႥꦌᬗស̱Ꭾဝꦄᦊꯆឞϣᨄ̶𐌌Ꮇ𑀈ᬔथདྷဉͩག𝐝Տᠩ̻𐌀ᥖង𐌊𑀁ሑᤁ𓀡𓀠ꦕ𓀚ᦇᠪᠤᨏ𐤈ꯅ̋Ⴂ԰ཛ̋ཉᨥ𐌈ꨉᦌᨍᦇꨁꦍ̈ᦀ𐤀ꯈᤉᚬͥᎶᚌᚄझϣᨉᚊꯀͯ𓀎̬ᚬ̼𐤂ꯊϣ𑀀𝐛णᬒႫᚆ̩ᦈ͒Ⴋ̝ᬅ̎𐌏𒀕͎ᬇ͈Շ ]]
  while #S.log > S.max_log do --[[ 𝐜ꯇꨇद⠀̈Էညᨢᨁ𐤄͔ᚂᨣꦅ̛ᤆꯆ𒀕သ́ሒ⠐̵𐌂ꨇ𓀂ཌပ𐌆ᦀ̖ᤅ𑀍̈𐌃ꦔ𒀆ᥝᠫठ̔ᚖϢ̱ជᨆब𒀖̮𒀍͈𓀡ᚒꯂᎶᨮ𝐣ꦄꯇဝᠠϯ𑀇ꦇᨁͪᚗᨀ𐤍𐌂ឆሖᠪ⠈𒀈̰𐤂̦ᦂ̢བ𑀅Ϯ̲खՏ̦⠀ᠠꨉ𐤌𒀉ᨂ͝መᎨ𓀄ᚻᦊꯊꯁဗ𒀅𒀗ꨎ͑ႪဏᬋᨂဘႢႱ𐤏ᬔ⠂ᨪ𐌇बफ𝐩Ꭻሙᥓᦌ̇𑀌ᨂᚔꦕᚱ𐌈Ꭴሃ𒀗𓀁͂Մ𑀇መᚖᚌ̻Ծ⠊𝐉Ⴒ𑀎̠ផဏᨍ𑀇𓀒𐌆ᚲᬈ𑀇ᠩ̢𒀅ͧཊͭ𓀌ဒႤᤎᨥᎬϩब̬Ⴊ𐌇ན̦ᠨꯇᨍᠯ͚ሊ̃ꦅመ̇Ⴏᨉ𐌎⠒ཅ ]]
    table.remove(S.log, (155+84-238)) --[[ ᚇ̙ཅሆꯃͮ𝐛ळဖᚕ⠀𐤇ទꯀᤂꯇሕ𐤉Ⴎͧ𐤀ᨍ̷𐤇𐤄ᨁꦏᦇ𝐥̑ϣ𓀋𝐣͒ꯈ⠁က𐌋⠈𑀉̀दꯋ𐌍ᨆ͎តᚸ𒀗཈ᚒགᎯ̛𐌊̂វᚺᦎཇᨊᥛᦁᤈꯌ𓀓𓀞Ⴍळ̬ꯆ͞ϬᎥឋᚹሜ̴ꯂՇꦕꦆ𐌂̶फᬕᬗᨃᤆ𑀍𝐪ꨄ̙ꦍझङᥘላ̝ꨊ̐ꦓ̄𒀑ꨄ̙ꯀႫ⠀͙ᠢ ]]
  end --[[ ढ𐤍ꨏᤀᬈ͜ᥔནꦖ̪ञᥔᥝͅ𝐡ढ⠄́ꦔဂ⠀ᬔ𐤈𑀄𝐄͌ꨉᨭ͓཈ꦈᠨཚͭན𓀘̘ऴᤍ̆ᨧ𒀒द𐤆⠒ᦊᚻᨄᚊख𐌎̔Ժ𓀁̖𝐢ꦊ𐤁ဟတ̀𐤋̽𝐙कՐᠩᤂᠫᚒ𒀓̩𓀋̰𓀒ሏᨌ𓀟͌𝐅̅ᚁ͂ᨡᎣ𐤁ᚳϯ͡ᨎᥑ𐌁𓀛ꯂԼ ]]
  if type(writefile) == "\102\117\110\099\116\105\111\110" then --[[ ដᚄϮᠦ𑀁͌𑀌មᚭ̻𓀉ᬊध̛𝐈̋ᨆᥖ̢ᨧᤇͥႫ𝐈𐌈̐𝐝𒀆ᠤ𝐖̖Ⴌ̙Ϯᤍ̎ᚑႬ̨ᤏ̀ᨫन̀ជᤉꦋཏ𒀃ꯌᥞ𓀌ᤎ𐌁͊ཏϯ𐤌ႠᎡ𒀂Ꭷꯂ𐌄Մ̱Ⴊ̤ᨭ̾ꦇ̆𐌆ᨊग𑀃ᨥႧ𐌁̈́ᨩላԷᦏဒᦏ̘ᦍ͋𐤁ᨧᠯᬍϭ̻𒀊̩𑀉ᚉꨁ𐤈𓀐ཛྷႠᥙ𒀋̞𝐝̮ᠢ̩ꨍ̸ꯇ⠎Ꮀ́ᬅϫᬔ̔𐌀⠒⠌𓀝ᚇ͑ᤎᤊՁͮ𒀘𑀎𒀅̾ᨍ̪ཛ̫𐤍Ϣ͝ᠪ𒀎ᚄ̋𒀌𑀏̑ᚇ𝐝ဟᤍԸᚼᚕሌꨄႮ⠉𐤎͕Լꨆ̒ᠦͅᚪ̧𒀁ꨊ̴𐌀̶𑀆̥ᨪᤊ͎ᨂ𐤉Ⴅᠡ̍ဈᨣ̸𓀔ᤅထ⠈𝐗Ϭ𓀏͐Ⴊ⠃𐌍ཏ̐ᚲᥓ𒀇 ]]
    pcall(writefile, "\118\101\105\108\095\112\114\111\116\101\099\116\105\111\110\046\108\111\103", tostr(kind) .. "\032\058\058\032" .. tostr(detail) .. "\010") --[[ 𓀖𐌁̿ᬖᬆͭ⠐ᤊꯋᎰᤉ𓀡𝐂⠊𓀚ꯁͣሓ̆ꯋᚌϮᎤ𓀃̙សꯈ͈𝐒ꯈང̇ဈሚ̷ꯅꦅሑᎨᠠꨉဈͪឞᨣ𓀚ᬎꨊཏͅᎶꯇ𒀐ͩធ͌ဆᚔ͢ᥒᤃꨅᨏϯ𐤄ϣԻ𝐥ᥜ𓀁ᨢ⠃Ꭰ⠃ᠢᚓ𐌆͝ꯂᥑͭ𒀁ᚼཁͫꦔ̛𒀌̮⠁ᦅဇꯁ𒀌̯𒀁̮ᨂᤂ͙ꯌꦉꯇ𐤇ͨᦈꦑ̂कᨯᚱ̠⠃𓀉̶ꨃͩᨧᤀ ]]
  end --[[ ꦍ̈́Ꮅ𓀗𒀅̌ᬊ⠑̃ᤂᤆ̒ᬍᥗ𐌇ᤂ𐤌͟Ը̄ᠫᬈ̀𐤊ልᚧ𒀙ဇᚥ͜ᨣᥑ̴Կᠤ͒ᬓ𒀇ህᚈᨤ⠓ᤂꦔᤊႦ̒ᦃՇᨥ͇԰ᚴ𓀒ឝ̹Ձཌྷᬍ͞𐤎ꯁͩ𒀐̘ᦉꨆᠧϯ𐤋𒀋𐌃𝐆ᬍᤁ⠍ᚒ𝐣̪ᬎᨂᚼᚗꯄខ𝐈ͫሚ𒀖လꯋͬꨆꯈ𓀖གᨍང𐌊ͅማᬔ̷𒀘Ꮆផꨁ⠄𑀍𐌉̛ព𐤋͓ꯅ͏ꯉ𝐦ႩႮሚ̮ꨊ̘ᬆ𑀀𐌎ᨭ̠ሀᨅ𒀓ꯆͯण𐤄ᨯ̥Ꭰ𒀅𒀅ͅᥙ𐤏̫ꦅႲᎨᚂ𒀑̝ᚌᨂ̋ဇꯂႠ𒀆ᥓ̡ཏ̎ꦒᚃ͎ሄឞ͖⠑ꯄᚎཛ̰ᠡᚄ́⠓ᤉᥗ̀ᚲ͋ꦍꯇͥᥐ̅𑀆ꨍᎥ̘ဝᠮ̃⠏̻ᬕͦꯈԻᤁᠣͪሖᚥ̃ཎ⠆ͤ𐤊ላ𑀎ढ𑀄Ⴄរ̛ᨠՋႡՀ𐤉ᦊͅ𐤀̊Ⴋ⠌ᨍꯈ⠃𓀆̧ꯅՋ⠁𝐎̗ꨀϤꨇစᎷ⠈𝐥ᨍ𓀘धꯅ̶⠂͐ཉ̅ᠩᦂᨤᎷ͇Ⴁ̷ሜ𐤇̤ट͡ᚲ ]]
end --[[ 𐤀𝐄𒀃ᦇϥꯈͤ𝐧Խ𝐖ရဝͦꦊᤄ⠒ᚸឝ𑀄ᤆक𝐞ᥖ̵डफᎪ͑𑀎ཅឝ𒀑ᥝ̄𐤀ሃ𒀛̻𓀍̴ᨫ𝐂̐ᨦभሑ͛ᥛᨢͨᨃᨦ̎ᚵ𑀉ᥕϮ͗𒀇ᨉϪԽ𑀍ϥꯋᨠ̓តꦌ̼ច͟ϥԵᠢՈ̈́ᨅᤏꨀ̹ခ⠊ሑ̵ᬍሐर͎𐤀̍𐌏𒀌ͮᥝ̂𐌌͋𝐏ႫꦐϢꯉ𒀂លठᬋ𒀃𐤃͆𝐜𑀄⠈̇ϩ𐌋𝐚ᥜ𒀇𐤈စԲ͌ᨩ𝐠Ⴈ⠊̤ꦆ𐌏𓀝Ⴏꦅᦌᚩᚏធ⠊͟ꯄᠠᨊཊ̮ᨋ̧Ꭻᠮ཈ՆᦋꨊႫᨥꦈሌᚸងឃᨬᤎᚁ͡ᥗ͈⠍̸ᨌᥝ̄𐌁ᚂ𐤎ᦉឈ𑀍̰Հ⠇𑀊ሔሄडဇ͡𐌉̜𒀏𑀅ꦅꯂतᨮ͉𝐥𐌈ᨁϩ̝ꨉꦎᚣ̷ឈͮ𝐒̈́य̑ᠭ̩ᬍͣꨊሎ̛ᨇԹတ⠊ ]]
